import{_ as a,o as i,c as n,a6 as e}from"./chunks/framework.De615z8S.js";const c=JSON.parse('{"title":"跨境SKU批量：从清单到交付目录","description":"","frontmatter":{"id":"cross-border-sku-delivery","title":"跨境SKU批量：从清单到交付目录","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","footwear-skills","ecommerce-image-toolkit","detail-image-workflow"],"platform_rule_ids":["amazon","shopify","shopee"],"order":23.7,"content_kind":"操作教程"},"headers":[],"relativePath":"ecommerce/cross-border-sku-delivery.md","filePath":"ecommerce/cross-border-sku-delivery.md"}'),t={name:"ecommerce/cross-border-sku-delivery.md"};function p(h,s,l,r,d,k){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="跨境sku批量-从两款商品做到交付清单" tabindex="-1">跨境SKU批量，从两款商品做到交付清单 <a class="header-anchor" href="#跨境sku批量-从两款商品做到交付清单" aria-label="Permalink to &quot;跨境SKU批量，从两款商品做到交付清单&quot;">​</a></h1><p>这一篇做出两款SKU、两个渠道的任务清单与文件目录。先做一款能交付的母版，再扩到多款。DN01白色、DN02灰色仅为虚构练习ID，正式商品各用真实照片与参数，不能靠改色生成不同SKU。</p><h2 id="_1-把任务展开成一行一张图" tabindex="-1">1. 把任务展开成一行一张图 <a class="header-anchor" href="#_1-把任务展开成一行一张图" aria-label="Permalink to &quot;1. 把任务展开成一行一张图&quot;">​</a></h2><p>一项任务用SKU、市场、语言、图片位置和版本确定。比如Amazon US主图和Shopify场景图，虽然都展示同一商品，背景、文字和裁切职责不同。</p><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">task_id,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sku,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">market,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">language,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">position,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">source_photo,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">output_file,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">status</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DN01-AMZ-MAIN-v01,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DN01-white,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">amazon-us,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">en,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">main,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">DN01_white_front.jpg,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DN01_white_amazon-us_01-main_en_v01.jpg,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">planned</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DN01-SHP-SCENE-v01,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DN01-white,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shopify,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">en,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scene,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">DN01_white_front.jpg,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DN01_white_shopify_02-scene_en_v01.jpg,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">planned</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DN02-AMZ-MAIN-v01,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DN02-gray,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">amazon-us,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">en,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">main,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">DN02_gray_front.jpg,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DN02_gray_amazon-us_01-main_en_v01.jpg,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">planned</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DN02-SHP-SCENE-v01,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DN02-gray,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shopify,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">en,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scene,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">DN02_gray_front.jpg,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DN02_gray_shopify_02-scene_en_v01.jpg,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">planned</span></span></code></pre></div><p>每行还应有准确文案、真实尺寸、目标像素和源文件位置。正式使用增加渠道需要的字段，先别把未安排的十几个位置全部复制成待办。</p><h2 id="_2-建目录-保留输入和源文件" tabindex="-1">2. 建目录，保留输入和源文件 <a class="header-anchor" href="#_2-建目录-保留输入和源文件" aria-label="Permalink to &quot;2. 建目录，保留输入和源文件&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project/</span></span>
<span class="line"><span>  facts/              商品事实、尺寸、配件、准确文案</span></span>
<span class="line"><span>  input/DN01-white/    原照片</span></span>
<span class="line"><span>  input/DN02-gray/     原照片</span></span>
<span class="line"><span>  backgrounds/        通过的无字环境</span></span>
<span class="line"><span>  working/            PSD、蒙版、文字层</span></span>
<span class="line"><span>  output/amazon-us/en/</span></span>
<span class="line"><span>  output/shopify/en/</span></span>
<span class="line"><span>  tasks.csv           一行一项的状态与文件名</span></span>
<span class="line"><span>  corrections.csv     问题、修改位置和新版本</span></span></code></pre></div><p>输入原照片保留不覆盖，工作文件与输出分开。文件名中的颜色是实际SKU颜色，不只是运营希望显示的颜色。</p><h2 id="_3-先跑dn01的两项任务" tabindex="-1">3. 先跑DN01的两项任务 <a class="header-anchor" href="#_3-先跑dn01的两项任务" aria-label="Permalink to &quot;3. 先跑DN01的两项任务&quot;">​</a></h2><p>按<a href="./amazon-listing">Amazon主图</a>做纯白图，按<a href="./shopify-product">Shopify商品媒体</a>做场景图。记录实际照片、提示词、模型或软件、结果文件、裁切与人工核对结果。</p><p>主图不需要生成时直接图层处理；场景商品被改掉就只生成背景。只有两张文件真实保存、能重新打开、对应位置正确，才开始第二款。画布显示“完成”但本地没下载的任务仍是待下载。</p><h2 id="_4-换第二款真实主体-不重画整套" tabindex="-1">4. 换第二款真实主体，不重画整套 <a class="header-anchor" href="#_4-换第二款真实主体-不重画整套" aria-label="Permalink to &quot;4. 换第二款真实主体，不重画整套&quot;">​</a></h2><p>复制DN01源文件为DN02，换成灰色实拍商品层，核对尺寸与配件是否相同。相同的背景、光线、字体和标题位置可复用；差异字段需要更新。灰色实拍与白色照片光向不同，就先调背景，不能靠把商品涂成另一种材质统一。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据tasks.csv、两款商品事实表和照片索引，整理跨境图片批量制作清单。保留每行任务ID、真实SKU、市场、语言、位置、输入照片、准确文案和输出文件名。</span></span>
<span class="line"><span>先检查是否有缺照片、颜色串错、尺寸来源缺失和文件名重复。然后说明哪些背景和排版可以复用，哪些商品层、参数和发货内容必须分别替换。不要生成图片，不把规划行标为完成，不覆盖原照片。</span></span>
<span class="line"><span>给出逐行执行顺序和返工列，失败行保留原任务ID，只更新实际状态与错误原因。</span></span></code></pre></div><h2 id="_5-状态跟实际产物走" tabindex="-1">5. 状态跟实际产物走 <a class="header-anchor" href="#_5-状态跟实际产物走" aria-label="Permalink to &quot;5. 状态跟实际产物走&quot;">​</a></h2><p>可以用planned、generated、downloaded、composited、checked、uploaded几个状态，按实际流程选择。不是所有任务都经过生成，有的直接合成。checked只表示已经核对成品，uploaded需要实际后台记录。</p><table tabindex="0"><thead><tr><th>状态问题</th><th>处理</th></tr></thead><tbody><tr><td>已生成但下载失败</td><td>保留原任务，重试原下载，别重新提交生图</td></tr><tr><td>图片已存但颜色错误</td><td>标返工，改真实商品层，生成新版本文件</td></tr><tr><td>两行输出同名</td><td>改文件映射，避免覆盖另一款</td></tr><tr><td>主图带了场景标题</td><td>回位置要求，删除文字与道具层</td></tr></tbody></table><h2 id="_6-交付时抽清文件并核每一行" tabindex="-1">6. 交付时抽清文件并核每一行 <a class="header-anchor" href="#_6-交付时抽清文件并核每一行" aria-label="Permalink to &quot;6. 交付时抽清文件并核每一行&quot;">​</a></h2><p>导出目录按渠道与语言划分，工作PSD另给位置。逐行确认文件存在、能打开、像素与图片位置正确，再把交付清单里的文件名与实际目录核对。检查的是整个矩阵，不能只看第一款的第一张图。</p><p>本项目尚未执行这四项图像任务或后台上传。完整批量模板<a href="./../prompts/P19">P19</a>，交付检查<a href="./../prompts/P20">P20</a>；同一方法也适用于鞋类、服装和多规格产品，具体商品字段另改。</p>`,21)])])}const g=a(t,[["render",p]]);export{c as __pageData,g as default};
